        evt('plant.fuel.issue_approved', actor, r.company_id, 'plt_fuel_issues', r.id, { issueId: r.id, docNo: r.doc_no, tankId: r.tank_id, tankCode: t.code, fuelType: t.fuel_type, equipmentId: r.equipment_id, assetCode: e.asset_code, classItemId: e.class_item_id, allocationId: r.allocation_id, projectId: r.org_project_id, siteId: r.org_site_id, issueAt: r.issue_at, litres: d3(r.litres), meterReading: d3(r.meter_reading), rate: r.rate / 100, cost: r.cost_amount / 100, consumption: r.consumption == null ? null : d3(r.consumption), norm: r.norm == null ? null : d3(r.norm), deviationPct: r.deviation_pct == null ? null : r.deviation_pct / 100, anomalies: db.prepare("SELECT rule_code FROM plt_fuel_anomalies WHERE issue_id = ? AND anomaly_status <> 'VOID'").all(r.id).map((x) => x.rule_code) }, r.org_project_id);
